"""
btssm factory
"""
from builtins import object
from ute_btssm import ute_btssm


class BtssmFactory(object):
    """
    Btssm factory
    """
    INSTANCE = None

    def __init__(self):
        self.oam_tool = ute_btssm()

    @classmethod
    def get_instance(cls):
        """
        Get instance
        """
        if not cls.INSTANCE:
            cls.INSTANCE = BtssmFactory()
        return cls.INSTANCE
